export const fresh = () => ({version:1, assets:[], selected:'', events:[], teams:[], incidents:[]});
export const selected = s => s.assets.find(a => a.id === s.selected);
const need = s => {const a=selected(s); if(!a) throw Error('Register or select an asset first.'); return a;};
export const passing = a => a.evidence?.revision === a.revision && a.evidence.checks.every(c=>c.passed);
export const approved = a => passing(a) && a.approval?.revision === a.revision;
export const ready = a => approved(a) && a.deployed === a.revision && a.violations < 3;
export function record(s,type,details={},asset=selected(s)?.id||null) {s.events.push({sequence:s.events.length+1,time:new Date().toISOString(),type,asset,details});}
const text = (v,name,max=1000) => {if(typeof v!=='string'||!v.trim()||v.length>max) throw Error(`Enter a valid ${name} (maximum ${max} characters).`);return v.trim();};
export function register(s,input){const a={id:crypto.randomUUID(),name:text(input.name,'asset name',100),owner:text(input.owner,'owner',80),model:text(input.model,'model version',80),purpose:text(input.purpose,'purpose'),risk:input.consequential?'High':input.sensitive?'Elevated':'Standard',sensitive:!!input.sensitive,consequential:!!input.consequential,revision:1,evidence:null,approval:null,deployed:null,violations:0,pending:[]};s.assets.push(a);s.selected=a.id;record(s,'asset_registered',{name:a.name,owner:a.owner,model:a.model,risk:a.risk});return a;}
export function evaluate(s,mode='pass'){const a=need(s);if(!['pass','leakage','fairness'].includes(mode))throw Error('Unknown scenario.');a.evidence={revision:a.revision,fixture:true,checks:['Grounding & abstention','Disclosure screening','Counterfactual similarity (illustrative)','Response consistency (illustrative)'].map((name,i)=>({name,passed:!(mode==='leakage'&&i===1)&&!(mode==='fairness'&&i>=2)}))};a.approval=null;a.deployed=null;a.pending=[];record(s,'evaluation_recorded',{mode,revision:a.revision,passed:passing(a),source:'illustrative_fixture'});}
export function approve(s,reviewer){const a=need(s);if(!passing(a))throw Error('Approval blocked: all checks must pass for the current model revision.');a.approval={revision:a.revision,reviewer:text(reviewer,'reviewer',80)};record(s,'human_approval_recorded',{...a.approval});}
export function deploy(s){const a=need(s);if(!approved(a))throw Error('Release blocked: current passing evidence and human approval are required.');a.deployed=a.revision;a.violations=0;record(s,'demo_release_deployed',{revision:a.revision});}
export function change(s,model){const a=need(s);model=text(model,'new model version',80);if(model===a.model)throw Error('Choose a different model version.');const previous=a.model;a.model=model;a.revision++;a.evidence=null;a.approval=null;a.deployed=null;a.pending=[];record(s,'model_changed',{previous,model,revision:a.revision});}
export function runtime(s,tool,query){const a=need(s);if(!ready(a)){record(s,'runtime_blocked',{reason:a.violations>=3?'circuit_open':'release_gate'});return 'BLOCKED: an approved demo release and a closed circuit breaker are required.';}query=text(query,'request');const normalized=query.normalize('NFKC').replace(/[\u200B-\u200F\uFEFF]/g,'').toLowerCase();if(!['search','propose_action'].includes(tool)||/ignore|system prompt|reveal.*secret/.test(normalized)){a.violations++;record(s,'policy_violation',{tool,violations:a.violations});return `BLOCKED: request violates the demo policy. Violations: ${a.violations}/3.${a.violations>=3?' Circuit breaker is open.':''}`;}if(tool==='propose_action'){const id=crypto.randomUUID();a.pending.push({id,revision:a.revision});record(s,'action_proposed',{id,revision:a.revision});return 'PENDING: select this action and record human approval to simulate execution.';}record(s,'runtime_search',{tool});return 'SIMULATED ANSWER: consult your approved benefits knowledge source. This walkthrough does not retrieve or generate a real answer.';}
export function execute(s,id){const a=need(s);if(!ready(a))throw Error('Action blocked: runtime release gate is closed.');const action=a.pending.find(p=>p.id===id&&p.revision===a.revision);if(!action)throw Error('Select a current pending action.');a.pending=a.pending.filter(p=>p.id!==id);record(s,'action_simulated',{id,revision:a.revision});}
export function incident(s,ref,occurred){ref=text(ref,'incident reference',100);const when=Date.parse(occurred);if(!Number.isFinite(when)||when>Date.now())throw Error('Incident occurrence must be a valid time in the past.');const i={id:crypto.randomUUID(),ref,occurred:new Date(when).toISOString(),detected:new Date().toISOString(),resolved:null};s.incidents.push(i);record(s,'incident_detected',i,null);}
export function resolve(s,id){const i=s.incidents.find(i=>i.id===id&&!i.resolved);if(!i)throw Error('Select an open incident.');i.resolved=new Date().toISOString();record(s,'incident_resolved',{id,resolved:i.resolved},null);}
export function metrics(events){const registered=events.filter(e=>e.type==='asset_registered'), evaluations=events.filter(e=>e.type==='evaluation_recorded'), releases=events.filter(e=>e.type==='demo_release_deployed');const cycles=releases.map(r=>{const reg=registered.find(e=>e.asset===r.asset);return reg?(Date.parse(r.time)-Date.parse(reg.time))/1000:null;}).filter(v=>v!==null);const first=evaluations.filter((e,i)=>evaluations.findIndex(p=>p.asset===e.asset)===i);let teams=[];for(const e of events)if(e.type==='eligible_teams_saved')teams=e.details.teams;const owners=new Set(registered.map(e=>e.details.owner));const detected=events.filter(e=>e.type==='incident_detected');const resolved=events.filter(e=>e.type==='incident_resolved');const avg=xs=>xs.length?xs.reduce((a,b)=>a+b,0)/xs.length:null;return{registeredAssets:registered.length,demoReleases:releases.length,meanCycleSeconds:avg(cycles),firstPassRate:first.length?first.filter(e=>e.details.passed).length/first.length:null,teamAdoptionRate:teams.length?teams.filter(t=>owners.has(t)).length/teams.length:null,policyViolations:events.filter(e=>e.type==='policy_violation').length,meanDetectionSeconds:avg(detected.map(e=>(Date.parse(e.details.detected)-Date.parse(e.details.occurred))/1000)),meanResolutionSeconds:avg(resolved.map(e=>{const d=detected.find(d=>d.details.id===e.details.id);return d?(Date.parse(e.details.resolved)-Date.parse(d.details.detected))/1000:null;}).filter(v=>v!==null)),waivers:events.filter(e=>e.type==='waiver_recorded').length};}
const sha=async text=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text))),b=>b.toString(16).padStart(2,'0')).join('');
export async function pack(events){let previous='GENESIS';const chain=[];for(const event of events){const hash=await sha(previous+'\n'+JSON.stringify(event));chain.push({event,previous,hash});previous=hash;}return{schema:'governance-demo-audit-v1',exportedAt:new Date().toISOString(),simulation:true,chain,head:previous,metrics:metrics(events)};}
export async function verify(pkg){if(pkg?.schema!=='governance-demo-audit-v1'||!Array.isArray(pkg.chain)||pkg.chain.length>10000)throw Error('Use a full audit package exported by this portal.');let previous='GENESIS';const events=[];const allowed=new Set(['asset_registered','evaluation_recorded','human_approval_recorded','demo_release_deployed','model_changed','runtime_blocked','policy_violation','action_proposed','runtime_search','action_simulated','incident_detected','incident_resolved','eligible_teams_saved','waiver_recorded']);for(const [index,row] of pkg.chain.entries()){const e=row.event;if(!e||e.sequence!==index+1||!Number.isFinite(Date.parse(e.time))||!allowed.has(e.type)||!e.details||typeof e.details!=='object')throw Error('Audit event schema is invalid.');if(e.type==='eligible_teams_saved'&&(!Array.isArray(e.details.teams)||!e.details.teams.every(t=>typeof t==='string')))throw Error('Invalid team data.');if(row.previous!==previous||row.hash!==await sha(previous+'\n'+JSON.stringify(e)))throw Error('Audit chain verification failed: modified or incomplete data.');events.push(e);previous=row.hash;}if(pkg.head!==previous)throw Error('Audit head does not match.');return metrics(events);}
